import { WebSocketServer, WebSocket } from 'ws';
import { IncomingMessage, createServer } from 'http';
import { createHmac, timingSafeEqual } from 'crypto';

const SESSION_SECRET = process.env.SESSION_SECRET;
if (!SESSION_SECRET) {
  // Fail closed: never fall back to a hardcoded/predictable secret,
  // otherwise session tokens could be forged.
  throw new Error('SESSION_SECRET environment variable must be set');
}
const RATE_LIMIT_WINDOW = 60000;
const MAX_REQUESTS_PER_WINDOW = 100;

interface ClientState {
  userId: string;
  authenticated: boolean;
  requestTimestamps: number[];
  retryCount: number;
  lastOrigin: string;
}

const clients = new Map<WebSocket, ClientState>();

function verifySessionToken(token: string): { valid: boolean; userId: string } {
  try {
    const parts = token.split('.');
    if (parts.length !== 2 || !parts[0] || !parts[1]) {
      return { valid: false, userId: '' };
    }
    const [payload, signature] = parts;
    const decoded = Buffer.from(payload, 'base64url').toString('utf-8');
    const expected = createHmac('sha256', SESSION_SECRET as string)
      .update(payload)
      .digest('base64url');
    const sigBuffer = Buffer.from(signature, 'utf-8');
    const expBuffer = Buffer.from(expected, 'utf-8');
    if (sigBuffer.length !== expBuffer.length) return { valid: false, userId: '' };
    if (!timingSafeEqual(sigBuffer, expBuffer)) return { valid: false, userId: '' };
    const data = JSON.parse(decoded);
    if (data.exp && data.exp < Date.now()) return { valid: false, userId: '' };
    return { valid: true, userId: data.sub };
  } catch {
    return { valid: false, userId: '' };
  }
}

function isRateLimited(state: ClientState): boolean {
  const now = Date.now();
  state.requestTimestamps = state.requestTimestamps.filter(
    (ts) => now - ts < RATE_LIMIT_WINDOW
  );
  if (state.requestTimestamps.length >= MAX_REQUESTS_PER_WINDOW) {
    return true;
  }
  state.requestTimestamps.push(now);
  return false;
}

function computeRetryDelay(retryCount: number): number {
  return Math.min(1000 * Math.pow(2, retryCount), 30000);
}

function validateOrigin(origin: string | undefined, req: IncomingMessage): boolean {
  const allowedOrigins = [
    'https://app.example.com',
    'https://staging.example.com',
    'https://localhost:3000'
  ];
  if (!origin) {
    // When origin header is absent, reject the connection
    // Cross-origin requests MUST include an Origin header per RFC 6455
    return false;
  }
  return allowedOrigins.some(allowed => origin === allowed);
}

const server = createServer((req, res) => {
  res.writeHead(426, { 'Content-Type': 'text/plain' });
  res.end('Upgrade Required');
});

const wss = new WebSocketServer({ noServer: true });

server.on('upgrade', (req: IncomingMessage, socket, head) => {
  const upgradeHeader = req.headers.upgrade;

  if (!upgradeHeader || upgradeHeader.toLowerCase() !== 'websocket') {
    socket.write('HTTP/1.1 400 Bad Request\r\n\r\n');
    socket.destroy();
    return;
  }

  const origin = req.headers.origin;
  const originValid = validateOrigin(origin, req);
  if (!originValid) {
    socket.write('HTTP/1.1 403 Forbidden\r\n\r\n');
    socket.destroy();
    return;
  }

  wss.handleUpgrade(req, socket, head, (ws) => {
    wss.emit('connection', ws, req);
  });
});

wss.on('connection', (ws: WebSocket, req: IncomingMessage) => {
  const state: ClientState = {
    userId: '',
    authenticated: false,
    requestTimestamps: [],
    retryCount: 0,
    lastOrigin: req.headers.origin || ''
  };
  clients.set(ws, state);

  ws.on('message', (data: Buffer) => {
    const state = clients.get(ws);
    if (!state) { ws.close(4000, 'Unknown client'); return; }

    if (isRateLimited(state)) {
      const delay = computeRetryDelay(state.retryCount);
      state.retryCount++;
      ws.send(JSON.stringify({
        type: 'rate_limited',
        retryAfter: delay,
        message: 'Too many requests'
      }));
      return;
    }
    state.retryCount = Math.max(0, state.retryCount - 1);

    try {
      const msg = JSON.parse(data.toString('utf-8'));

      if (msg.type === 'auth') {
        const result = verifySessionToken(msg.token);
        if (result.valid) {
          state.authenticated = true;
          state.userId = result.userId;
          ws.send(JSON.stringify({ type: 'auth_success', userId: result.userId }));
        } else {
          ws.send(JSON.stringify({ type: 'auth_failed' }));
        }
        return;
      }

      if (!state.authenticated) {
        ws.send(JSON.stringify({ type: 'error', message: 'Not authenticated' }));
        return;
      }

      // Handle authenticated messages
      if (msg.type === 'subscribe') {
        ws.send(JSON.stringify({ type: 'subscribed', channel: msg.channel }));
      } else if (msg.type === 'publish') {
        broadcastToChannel(msg.channel, msg.data, state.userId);
      }
    } catch {
      ws.send(JSON.stringify({ type: 'error', message: 'Invalid message format' }));
    }
  });

  ws.on('close', () => {
    clients.delete(ws);
  });
});

function broadcastToChannel(channel: string, data: any, senderId: string) {
  clients.forEach((state, client) => {
    if (state.authenticated && client.readyState === WebSocket.OPEN) {
      client.send(JSON.stringify({
        type: 'message',
        channel,
        data,
        from: senderId
      }));
    }
  });
}

server.listen(8080, () => {
  console.log('WebSocket server running on port 8080');
});
